<script setup>
import {Check,Plus,ChevronRight,X} from '@lucide/vue';import {levelLabel} from '../lib/spells';
defineProps({spells:Array,selectedId:Number,pendingIds:{type:Array,default:()=>[]},preparing:Boolean,canUse:Function,usingId:Number,showUse:Boolean});defineEmits(['select','toggle','use']);
</script>
<template><div class="spell-table" :class="{'with-use':showUse}"><div class="table-heading"><span>Magia</span><span>Escola</span><span>{{preparing?'Preparação':'Conjuração'}}</span></div><div v-for="spell in spells" :key="spell.id" class="spell-row" :class="{selected:selectedId===spell.id}"><button class="spell-name-button" @click="$emit('select',spell.id)"><span class="circle-number" :title="levelLabel(spell.level)">{{spell.level===0?'T':spell.level}}</span><span><strong>{{spell.name}}</strong><small>{{levelLabel(spell.level)}}<template v-if="spell.sourceKind==='homebrew'"> · Homebrew</template></small></span><ChevronRight :size="16" class="row-chevron"/></button><span class="school-cell">{{spell.school}}</span><div class="row-end"><button v-if="preparing" class="prepare-button" :class="{prepared:spell.isPrepared}" :disabled="pendingIds.includes(spell.id)||(!spell.isPrepared&&!spell.canPrepare)" :aria-label="`${spell.isPrepared?'Remover':'Preparar'} ${spell.name}`" :title="spell.canPrepare||spell.isPrepared?'':'Fora da lista da classe do personagem'" @click="$emit('toggle',spell)"><Check v-if="spell.isPrepared" :size="16"/><Plus v-else :size="16"/><span>{{pendingIds.includes(spell.id)?'Salvando…':spell.isPrepared?'Preparada':spell.canPrepare?'Preparar':'Outra classe'}}</span></button><template v-else><button v-if="showUse" class="button use-spell" :disabled="!canUse?.(spell)||pendingIds.includes(spell.id)" :aria-label="`Usar magia ${spell.name}`" :title="spell.level===0?'Truque: não gasta espaços':canUse?.(spell)?'Gastar um espaço deste círculo':'Sem espaços disponíveis ou operação em andamento'" @click="$emit('use',spell)">{{usingId===spell.id?'Usando…':'Usar magia'}}</button><span class="casting-cell" :title="spell.castingTime">{{spell.castingTime}}</span><button class="icon-button remove-button" :disabled="pendingIds.includes(spell.id)||usingId!=null" :aria-label="`Remover ${spell.name} das preparadas`" @click="$emit('toggle',spell)"><X :size="16"/></button></template></div></div></div></template>
<style scoped>
.with-use .table-heading,.with-use .spell-row{grid-template-columns:minmax(180px,1fr) 130px 280px}
.with-use .row-end{display:grid;grid-template-columns:98px minmax(0,1fr) 30px;gap:10px;min-width:0;padding-top:10px;padding-bottom:10px}
.with-use .casting-cell{min-width:0;line-height:1.5;overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-clamp:2;overflow-wrap:anywhere}
.use-spell{font-size:.75rem;min-height:36px;padding:7px 9px;white-space:nowrap;flex-shrink:0}
@media(max-width:1100px){.with-use .table-heading,.with-use .spell-row{grid-template-columns:minmax(160px,1fr) 100px 260px}}
@media(max-width:760px){.with-use .spell-row{grid-template-columns:minmax(0,1fr) auto}.with-use .row-end{grid-template-columns:98px 30px;gap:6px}.with-use .casting-cell{display:none}}
</style>